-- Dump completed on 2026-11-08 14:07:02

-- Thông báo trang quản trị (chuông) và yêu cầu xoá dự án cần Admin khác duyệt.
-- Thời gian lưu theo UTC. Ứng dụng cũng tự tạo các bảng này khi chạy (ensureProjectEventsSchema).
CREATE TABLE IF NOT EXISTS project_deletion_requests (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  project_id VARCHAR(64) NOT NULL,
  project_name VARCHAR(255) NOT NULL,
  requested_by VARCHAR(64) NOT NULL,
  requested_by_name VARCHAR(100) NOT NULL,
  status VARCHAR(20) NOT NULL DEFAULT 'pending',
  decided_by VARCHAR(64) NULL,
  decided_by_name VARCHAR(100) NULL,
  created_at DATETIME(3) NOT NULL,
  decided_at DATETIME(3) NULL,
  PRIMARY KEY (id),
  KEY idx_project_deletion_project (project_id, status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS admin_notifications (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  type VARCHAR(40) NOT NULL,
  project_id VARCHAR(64) NOT NULL,
  project_name VARCHAR(255) NOT NULL,
  actor_id VARCHAR(64) NULL,
  actor_name VARCHAR(100) NULL,
  request_id BIGINT UNSIGNED NULL,
  detail VARCHAR(255) NULL,
  created_at DATETIME(3) NOT NULL,
  PRIMARY KEY (id),
  KEY idx_admin_notifications_created (created_at),
  KEY idx_admin_notifications_project (project_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Lịch sử gắn / thay đồng hồ của điểm đo (UTC). Biên bản thay đồng hồ: final_index = chỉ số chốt đồng hồ cũ,
-- initial_index = chỉ số ban đầu đồng hồ mới (kWh). Điện năng được nối liên tục qua các lần thay (lib/meter-continuity.ts).
CREATE TABLE IF NOT EXISTS meter_point_history (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  project_id VARCHAR(64) NOT NULL,
  meter_point_id VARCHAR(100) NOT NULL,
  category VARCHAR(100) NULL,
  serial_number VARCHAR(100) NOT NULL,
  valid_from DATETIME NOT NULL DEFAULT '2020-01-01 00:00:00',
  valid_to DATETIME NULL,
  final_index DECIMAL(18,6) NULL,
  initial_index DECIMAL(18,6) NULL,
  replaced_by VARCHAR(100) NULL,
  recorded_at DATETIME NULL,
  PRIMARY KEY (id),
  KEY idx_mph_point (project_id, meter_point_id, valid_from)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Các lần hệ thống nghi thay đồng hồ (chỉ số tụt, không hồi lại) chờ quản trị viên nhập biên bản / bỏ qua.
CREATE TABLE IF NOT EXISTS meter_reset_suspects (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  project_id VARCHAR(64) NOT NULL,
  meter_point_id VARCHAR(100) NOT NULL,
  serial_number VARCHAR(100) NOT NULL,
  detected_at DATETIME NOT NULL,
  before_index DECIMAL(18,6) NOT NULL,
  after_index DECIMAL(18,6) NOT NULL,
  status VARCHAR(20) NOT NULL DEFAULT 'open',
  created_at DATETIME NOT NULL,
  PRIMARY KEY (id),
  KEY idx_mrs_point (project_id, meter_point_id, detected_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS admin_notification_seen (
  account_id VARCHAR(64) NOT NULL,
  seen_at DATETIME(3) NOT NULL,
  PRIMARY KEY (account_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Thư viện cảnh báo dùng chung theo loại điểm đo (Cấu hình → Thư viện cảnh báo).
-- Một dòng id = 'default', payload = { categoriesByUtility, alarmsByCategory } (cùng cấu trúc alertConfig của dự án).
-- Ứng dụng cũng tự tạo bảng này khi chạy (ensureAlertLibrarySchema).
CREATE TABLE IF NOT EXISTS alert_library (
  id VARCHAR(32) NOT NULL,
  payload JSON NOT NULL,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Thư viện mẫu báo cáo dùng chung theo loại điểm đo (Cấu hình → Thư viện báo cáo).
-- payload = { headerFooter, enabledReports, fieldsByReport, titles, layout }.
-- Ứng dụng tự tạo bảng này khi chạy và thêm sẵn 4 mẫu cho loại Điện nếu bảng trống (ensureReportTemplatesSchema).
CREATE TABLE IF NOT EXISTS report_templates (
  id VARCHAR(64) NOT NULL,
  meter_type VARCHAR(100) NOT NULL,
  name VARCHAR(200) NOT NULL,
  payload JSON NOT NULL,
  sort_order INT NOT NULL DEFAULT 0,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_report_templates_type (meter_type, sort_order)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SET FOREIGN_KEY_CHECKS = 1;
